contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint b1 = address(c).balance;
        uint b2 = address(this).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint b3 = address(c).balance;
        assert(b3 == 0 && b1 == 0 && b2 == address(this).balance);
    }
}

